def find_kid_action(image):
    image_patch = ImagePatch(image)
    kid_patches = image_patch.find("kid")
    if not kid_patches:
        return "No kid found in the image."
    # sort patches by the distance to the center of the image
    center_x = image.shape[1] / 2
    center_y = image.shape[0] / 2
    kid_patches.sort(key=lambda patch: math.sqrt((patch.left + patch.right) / 2 - center_x)**2 + math.sqrt((patch.lower + patch.upper) / 2 - center_y)**2)
    return kid_patches[0].llm_query("What is the kid doing?", long_answer=False)

